/** Java 8 mailbox adapter to the existing launcher friend service. No cloud account tokens enter Minecraft. */
public final class SocialBridge {
 private static final ExecutorService IO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"Unbox friends IO");t.setDaemon(true);return t;});
 public static volatile JsonObject view=new JsonObject();public static volatile String message="";
 private static volatile boolean queued,guarded,joining;private static boolean commandOk;public static boolean commandSucceeded(){return commandOk;}public static boolean notificationSeen(String id){if(seen.contains(id))return true;try{for(JsonElement v:view.getAsJsonArray("seenInvites"))if(v.getAsString().equals(id))return true;}catch(RuntimeException ignored){}return false;}public static void seen(String id){seen.add(id);}private static boolean directJoin,relayRetried;private static boolean wasWorld,resumeLoaded;private static long nextPoll,commandAt,joinAt,joinGeneration;private static String commandId="",lastAction="",lastAck="",attempt="",resume="";private static long resumeUntil;
 private static volatile JsonObject room;private static UUID owner;private static final Set<UUID> invited=ConcurrentHashMap.newKeySet();private static DatagramSocket discovery;private static volatile String pendingJoin="";private static volatile UnboxRelay relay;private static long relayAt;
 private static final Set<String> seen=ConcurrentHashMap.newKeySet();
 static Path root(){return Minecraft.getMinecraft().mcDataDir.toPath();}
 public static boolean guarded(){return guarded;}public static boolean allowed(UUID id){return !guarded||invited.contains(id);}public static boolean hosting(){return room!=null;}public static boolean joining(){return joining;}public static boolean pending(){return !commandId.isEmpty();}
 public static String text(JsonObject o,String k){try{return o!=null&&o.has(k)&&!o.get(k).isJsonNull()?o.get(k).getAsString():"";}catch(RuntimeException e){return "";}}
 public static boolean flag(JsonObject o,String k){return "true".equals(text(o,k));}
 static JsonObject copy(JsonObject o){return new JsonParser().parse(o.toString()).getAsJsonObject();}
 public static List<JsonObject> rows(String key){List<JsonObject> out=new ArrayList<>();try{for(JsonElement e:view.getAsJsonArray(key))if(e.isJsonObject())out.add(e.getAsJsonObject());}catch(RuntimeException ignored){}return out;}
 static String self(){return view.has("self")&&view.get("self").isJsonObject()?text(view.getAsJsonObject("self"),"id"):"";}
 static boolean connected(){return flag(view,"connected");}
 static UUID uuid(String id){return UUID.fromString(id.replaceFirst("^(........)(....)(....)(....)(............)$","$1-$2-$3-$4-$5"));}
 static JsonObject read(String name){try{Path p=root().resolve(name);if(Files.size(p)>2_000_000)return new JsonObject();return new JsonParser().parse(new String(Files.readAllBytes(p),StandardCharsets.UTF_8)).getAsJsonObject();}catch(Exception e){return new JsonObject();}}
 static void write(String name,JsonObject data)throws Exception{Path tmp=root().resolve(".unbox-"+UUID.randomUUID()+".tmp");try{if(Files.getFileStore(root()).supportsFileAttributeView("posix"))Files.createFile(tmp,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));else Files.createFile(tmp);Files.write(tmp,data.toString().getBytes(StandardCharsets.UTF_8));Files.move(tmp,root().resolve(name),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}finally{Files.deleteIfExists(tmp);}}
 static void background(Runnable r){IO.submit(r);}static void main(Runnable r){Minecraft.getMinecraft().addScheduledTask(r);}
 public static boolean command(String op,String id){if(pending()){message="Wait for the previous request";return false;}if(!connected()){message="Friends are offline. Keep the launcher open and retry.";return false;}commandOk=false;commandId=UUID.randomUUID().toString();commandAt=System.currentTimeMillis();JsonObject c=new JsonObject();c.addProperty("requestId",commandId);c.addProperty("op",op);c.addProperty("id",id);c.addProperty("at",commandAt);background(()->{try{write("unbox-social-command.json",c);}catch(Exception e){main(()->{commandId="";message="Could not contact the launcher";});}});return true;}
 private static JsonObject world(){Minecraft mc=Minecraft.getMinecraft();JsonObject w=new JsonObject();boolean local=mc.theWorld!=null&&mc.getIntegratedServer()!=null;w.addProperty("updated",System.currentTimeMillis());w.addProperty("accountName",mc.getSession().getUsername());w.addProperty("accountUuid",mc.getSession().getProfile().getId().toString().replace("-",""));w.addProperty("inWorld",local);w.addProperty("canInvite",local);w.addProperty("joining",joining);w.addProperty("error",message);JsonArray ids=new JsonArray();if(mc.getNetHandler()!=null)for(net.minecraft.client.network.NetworkPlayerInfo p:mc.getNetHandler().getPlayerInfoMap())ids.add(new JsonPrimitive(p.getGameProfile().getId().toString().replace("-","")));w.add("players",ids);w.add("routeSignals",VoxLinkNetwork.signals());JsonArray marks=new JsonArray();for(String id:seen)marks.add(new JsonPrimitive(id));w.add("seenInvites",marks);if(room!=null){JsonObject r=copy(room);UnboxRelay s=relay;if(s!=null&&!s.domain.isEmpty())r.addProperty("relay",s.domain);w.add("room",r);w.add("grants",PrivateLogin.secrets());}return w;}
 static void tick(){Minecraft mc=Minecraft.getMinecraft();long now=System.currentTimeMillis();JoinDiagnostics.tick(mc);VoxLinkNetwork.tick(room);boolean local=mc.theWorld!=null&&mc.getIntegratedServer()!=null;if(wasWorld&&!local)stop();wasWorld=local;
  if(pending()&&now-commandAt>20000){commandId="";message="Request timed out. Please retry.";}
  if(joining&&mc.theWorld!=null&&mc.getIntegratedServer()==null){joining=false;pendingJoin="";seen.add(attempt);JoinDiagnostics.finish("joined");message="";}
  if(joining&&mc.currentScreen instanceof GuiDisconnected){if(!retryDirect((GuiDisconnected)mc.currentScreen)){joining=false;pendingJoin="";PrivateLogin.cancelJoin();VoxLinkNetwork.cancelJoin();JoinDiagnostics.finish("failed");message="Connection failed. Open Worlds to retry the invitation.";}}
  if(joining&&now-joinAt>90000){cancelJoin();Minecraft.getMinecraft().displayGuiScreen(new HomeScreen(false));message="Connection timed out. Request a new invitation or retry.";}
  if(!resume.isEmpty()&&now>resumeUntil){resume="";message="Invitation expired. Request a new invitation.";}
  if(now<nextPoll||queued)return;nextPoll=now+500;queued=true;final JsonObject w=world();
  background(()->{try{write("unbox-world.json",w);final JsonObject next=read("unbox-social-view.json"),action=read("unbox-social-action.json"),ack=read("unbox-social-ack.json"),restore=resumeLoaded?null:read("unbox-rejoin.json");if(restore!=null)Files.deleteIfExists(root().resolve("unbox-rejoin.json"));main(()->{accept(next,action,ack);if(!resumeLoaded){resumeLoaded=true;if(restore!=null&&restore.has("expires")&&restore.get("expires").getAsLong()>System.currentTimeMillis()&&text(restore,"accountUuid").replace("-","").equals(mc.getSession().getProfile().getId().toString().replace("-",""))){resume=text(restore,"id");resumeUntil=restore.get("expires").getAsLong();}}
    if(connected()&&!resume.isEmpty()&&findInvite(resume)!=null){String id=resume;resume="";join(id);}if(room!=null)for(JsonObject i:rows("invites"))if(text(i,"sender").equals(self())&&"1".equals(text(i,"relay_requested")))startRelay();if(!pendingJoin.isEmpty()){JsonObject i=findInvite(pendingJoin);if(i!=null){String address=text(i.getAsJsonObject("room"),"relay");if(!address.isEmpty()){pendingJoin="";connect(address);}}}});
   }catch(Exception e){main(()->message="Launcher connection unavailable. Please retry.");}finally{queued=false;}});
 }
 static void accept(JsonObject next,JsonObject action,JsonObject ack){long now=System.currentTimeMillis();boolean fresh=next.has("updated")&&now-next.get("updated").getAsLong()<60000&&now>=next.get("updated").getAsLong()-5000;
  if(fresh&&next.has("self")&&next.get("self").isJsonObject()){String account=text(next.getAsJsonObject("self"),"uuid");if(!account.replace("-","").equals(Minecraft.getMinecraft().getSession().getProfile().getId().toString().replace("-","")))fresh=false;}
  if(fresh)view=next;else{JsonObject cached=copy(view);cached.addProperty("connected",false);cached.add("invites",new JsonArray());if(cached.has("friends"))for(JsonElement f:cached.getAsJsonArray("friends"))f.getAsJsonObject().addProperty("online",false);view=cached;}
  if(guarded&&connected()){Set<UUID> accepted=new HashSet<>();if(owner!=null)accepted.add(owner);for(JsonObject f:rows("friends"))if("1".equals(text(f,"accepted")))try{accepted.add(uuid(text(f,"uuid")));}catch(IllegalArgumentException ignored){}invited.retainAll(accepted);PrivateLogin.retain(invited);kickUninvited();}
  String id=text(action,"requestId");if(!id.isEmpty()&&!id.equals(lastAction)&&action.has("at")&&Math.abs(now-action.get("at").getAsLong())<15000){lastAction=id;if(text(action,"op").equals("invite"))invite(text(action,"id"));else if(text(action,"op").equals("join"))join(text(action,"id"));}
  id=text(ack,"requestId");if(!id.isEmpty()&&!id.equals(lastAck)){lastAck=id;if(id.equals(commandId)){commandId="";commandOk=flag(ack,"ok");message=commandOk?"Request completed":text(ack,"error");}}
 }
 public static void invite(String id){if(!connected()){message="Friends are offline";return;}if(pending())return;Minecraft mc=Minecraft.getMinecraft();IntegratedServer server=mc.getIntegratedServer();if(server==null||mc.theWorld==null){message="Open a singleplayer world before inviting";return;}JsonObject friend=null;for(JsonObject f:rows("friends"))if(text(f,"id").equals(id)&&text(f,"accepted").equals("1"))friend=f;if(friend==null){message="Friend not found";return;}
  try{UUID peer=uuid(text(friend,"uuid"));if(room==null){if(server.getPublic()){message="Reopen this world before starting private sharing";return;}owner=mc.getSession().getProfile().getId();invited.clear();invited.add(owner);guarded=true;server.setOnlineMode(true);String port=server.shareToLAN(server.getGameType(),false);if(port==null)throw new IllegalStateException();JsonObject r=new JsonObject();r.addProperty("id",UUID.randomUUID().toString());r.addProperty("protocol",2);r.addProperty("loader","forge");r.addProperty("minecraft","1.8.9");r.addProperty("name",server.getWorldName());r.addProperty("port",Integer.parseInt(port));r.addProperty("probeToken",UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-",""));JsonArray lan=new JsonArray();for(NetworkInterface ni:Collections.list(NetworkInterface.getNetworkInterfaces()))if(ni.isUp()&&!ni.isLoopback())for(InetAddress a:Collections.list(ni.getInetAddresses()))if(a instanceof Inet4Address&&a.isSiteLocalAddress()&&lan.size()<8)lan.add(new JsonPrimitive(a.getHostAddress()));r.add("lan",lan);discovery=new DatagramSocket(0);r.addProperty("probePort",discovery.getLocalPort());r.addProperty("network",VoxLinkNetwork.VERSION);room=r;discover(discovery,text(r,"probeToken"));}
   PrivateLogin.grant(id,peer,text(friend,"name"),text(room,"id"));invited.add(peer);JsonObject w=world();message="Sending invitation…";background(()->{try{write("unbox-world.json",w);main(()->command("send",id));}catch(Exception e){main(()->message="Could not send invitation");}});
  }catch(Exception e){message="Could not open this world. Reopen it and retry.";}
 }
 private static void discover(final DatagramSocket socket,String token){Thread t=new Thread(()->{byte[] q=("UNBOX?"+token).getBytes(StandardCharsets.US_ASCII),a=("UNBOX!"+token).getBytes(StandardCharsets.US_ASCII);while(!socket.isClosed())try{DatagramPacket p=new DatagramPacket(new byte[128],128);socket.receive(p);if(p.getAddress().isSiteLocalAddress()&&Arrays.equals(Arrays.copyOf(p.getData(),p.getLength()),q))socket.send(new DatagramPacket(a,a.length,p.getSocketAddress()));}catch(Exception e){break;}},"Unbox LAN discovery");t.setDaemon(true);t.start();}
 static JsonObject findInvite(String id){for(JsonObject i:rows("invites"))try{if(text(i,"id").equals(id)&&text(i,"receiver").equals(self())&&i.get("expires").getAsLong()>System.currentTimeMillis())return i;}catch(RuntimeException ignored){}return null;}
 static List<JsonObject> worlds(){List<JsonObject> out=new ArrayList<>();for(JsonObject i:rows("invites"))if(findInvite(text(i,"id"))!=null)out.add(i);return out;}
 public static void join(String id){if(joining)return;JsonObject i=findInvite(id);if(i==null||!connected()){message="Invitation expired or friends are offline";return;}final JsonObject r=i.getAsJsonObject("room");Minecraft mc=Minecraft.getMinecraft();GuiScreen parent=mc.currentScreen;
  if(mc.theWorld!=null){mc.displayGuiScreen(new GuiYesNo((yes,n)->{if(!yes){mc.displayGuiScreen(parent);return;}mc.theWorld.sendQuittingDisconnectingPacket();mc.loadWorld(null);mc.displayGuiScreen(new HomeScreen(false));join(id);},"Leave this world?","Join your friend's world",0));return;}
  if(!text(r,"minecraft").equals("1.8.9")||!text(r,"loader").equals("forge")){mc.displayGuiScreen(new GuiYesNo((yes,n)->{if(!yes){mc.displayGuiScreen(parent);return;}JsonObject request=new JsonObject();request.addProperty("id",id);request.addProperty("accountUuid",mc.getSession().getProfile().getId().toString());request.addProperty("at",System.currentTimeMillis());background(()->{try{write("unbox-switch-request.json",request);main(mc::shutdown);}catch(Exception e){main(()->{message="Could not switch versions";mc.displayGuiScreen(parent);});}});},"Switch game version?","Restart with "+text(r,"minecraft")+" / "+text(r,"loader"),0));return;}
  try{PrivateLogin.prepare(i);}catch(Exception e){message="Ask your friend for an updated invitation";return;}JoinDiagnostics.begin();attempt=id;seen.add(id);directJoin=false;relayRetried=false;joining=true;joinAt=System.currentTimeMillis();final long generation=++joinGeneration;message="Finding your friend's world…";mc.displayGuiScreen(new JoinScreen(parent));background(()->{String address=probe(r);main(()->{if(!joining||generation!=joinGeneration)return;if(address!=null){directJoin=true;JoinDiagnostics.route("lan");connect(address);}else{VoxLinkNetwork.join(i).whenComplete((route,error)->main(()->{if(!joining||generation!=joinGeneration)return;if(route!=null&&error==null){directJoin=true;JoinDiagnostics.route(route.kind());connect(route.address());}else{VoxLinkNetwork.cancelJoin();requestRelay(i);}}));}});});
 }
 private static void requestRelay(JsonObject invite){JoinDiagnostics.route("relay");directJoin=false;joinAt=System.currentTimeMillis();String address=text(invite.getAsJsonObject("room"),"relay");if(!address.isEmpty())connect(address);else{pendingJoin=text(invite,"id");message="Preparing internet connection…";if(!command("relay",pendingJoin)){cancelJoin();message="Could not request relay. Please retry.";}}}
 public interface DisconnectReason {net.minecraft.util.IChatComponent unboxReason();}
 private static boolean retryDirect(GuiDisconnected screen){if(!directJoin||relayRetried||!(screen instanceof DisconnectReason))return false;net.minecraft.util.IChatComponent reason=((DisconnectReason)screen).unboxReason();if(!(reason instanceof net.minecraft.util.ChatComponentTranslation))return false;String key=((net.minecraft.util.ChatComponentTranslation)reason).getKey();boolean retry=key.equals("disconnect.endOfStream")||key.equals("disconnect.timeout")||key.equals("disconnect.genericReason")&&reason.getUnformattedText().matches("(?s).*(IOException|SocketException|ConnectException|ClosedChannelException|ReadTimeoutException|SocketTimeoutException|Connection reset|Connection refused|Network is unreachable|No route to host|Broken pipe).*" );if(!retry)return false;JsonObject invite=findInvite(attempt);if(invite==null)return false;try{PrivateLogin.prepare(invite);}catch(Exception e){return false;}relayRetried=true;directJoin=false;joinGeneration++;VoxLinkNetwork.cancelJoin();Minecraft.getMinecraft().displayGuiScreen(new JoinScreen(new HomeScreen(false)));requestRelay(invite);return true;}
 private static String probe(JsonObject r){try(DatagramSocket socket=new DatagramSocket()){socket.setSoTimeout(250);String token=text(r,"probeToken");if(!token.matches("[a-f0-9]{64}"))return null;byte[] q=("UNBOX?"+token).getBytes(StandardCharsets.US_ASCII),a=("UNBOX!"+token).getBytes(StandardCharsets.US_ASCII);List<InetAddress> hosts=new ArrayList<>();for(JsonElement e:r.getAsJsonArray("lan")){String h=e.getAsString();if(!h.matches("\\d{1,3}(\\.\\d{1,3}){3}"))continue;InetAddress ip=InetAddress.getByName(h);if(ip.isSiteLocalAddress()&&sameSubnet(ip))hosts.add(ip);}int port=r.get("probePort").getAsInt();for(int n=0;n<3;n++){for(InetAddress h:hosts)socket.send(new DatagramPacket(q,q.length,h,port));try{DatagramPacket p=new DatagramPacket(new byte[128],128);socket.receive(p);if(hosts.contains(p.getAddress())&&p.getPort()==port&&Arrays.equals(Arrays.copyOf(p.getData(),p.getLength()),a))return p.getAddress().getHostAddress()+":"+r.get("port").getAsInt();}catch(SocketTimeoutException ignored){}}}catch(Exception ignored){}return null;}
 private static boolean sameSubnet(InetAddress remote)throws Exception{if(!(remote instanceof Inet4Address))return false;int r=java.nio.ByteBuffer.wrap(remote.getAddress()).getInt();for(NetworkInterface ni:Collections.list(NetworkInterface.getNetworkInterfaces()))if(ni.isUp())for(InterfaceAddress a:ni.getInterfaceAddresses())if(a.getAddress() instanceof Inet4Address){int bits=a.getNetworkPrefixLength();if(bits<1||bits>32)continue;int mask=(int)(0xffffffffL<<(32-bits));if((java.nio.ByteBuffer.wrap(a.getAddress().getAddress()).getInt()&mask)==(r&mask))return true;}return false;}
 static void connect(String address){if(!address.matches("(?:[a-z0-9.-]+\\.e4mc\\.link|\\d{1,3}(?:\\.\\d{1,3}){3}:\\d{1,5})")){cancelJoin();message="Invalid world address";return;}message="Connecting to private world…";Minecraft mc=Minecraft.getMinecraft();mc.displayGuiScreen(new GuiConnecting(new JoinScreen(new HomeScreen(false)),mc,new ServerData("Friend's world",address,false)));}
 public interface CancelConnection {void unboxCancel();}
 public static void cancelJoin(){if(Minecraft.getMinecraft().currentScreen instanceof CancelConnection)((CancelConnection)Minecraft.getMinecraft().currentScreen).unboxCancel();JoinDiagnostics.finish("cancelled");VoxLinkNetwork.cancelJoin();directJoin=false;joining=false;pendingJoin="";resume="";joinGeneration++;PrivateLogin.cancelJoin();message="Join cancelled";}
 static void startRelay(){if(room==null||relay!=null)return;relayAt=System.currentTimeMillis();try{relay=new UnboxRelay(room.get("port").getAsInt());relay.startAsync();message="Starting internet sharing…";}catch(Throwable e){relay=null;message="Internet sharing unavailable. Retry relay.";}}
 static boolean relayFailed(){return relay!=null&&(relay.state==UnboxRelay.State.UNHEALTHY||relay.state==UnboxRelay.State.STOPPED||relay.domain.isEmpty()&&System.currentTimeMillis()-relayAt>60000);}
 static void retryRelay(){UnboxRelay old=relay;relay=null;if(old!=null)old.stop();startRelay();}
 private static void kickUninvited(){IntegratedServer s=Minecraft.getMinecraft().getIntegratedServer();if(s!=null)s.addScheduledTask(()->{for(EntityPlayerMP p:new ArrayList<EntityPlayerMP>(s.getConfigurationManager().getPlayerList()))if(!allowed(p.getUniqueID()))p.playerNetServerHandler.kickPlayerFromServer("World sharing ended.");});}
 public static void stopSharing(){VoxLinkNetwork.stopHosting();PrivateLogin.clearHost();invited.clear();if(owner!=null)invited.add(owner);kickUninvited();room=null;if(discovery!=null){discovery.close();discovery=null;}UnboxRelay old=relay;relay=null;if(old!=null)old.stop();message="Sharing stopped. Reopen the world to host again.";}
 static void stop(){stopSharing();guarded=false;owner=null;invited.clear();if(!joining)message="";}
}
